const char* lib_libmount_so_1 = "lib_libmount_so_1";
const char* lib_libacl_so_1 = "lib_libacl_so_1";
const char* lib_libcrypto_so_3 = "lib_libcrypto_so_3";
const char* lib_libzstd_so_1 = "lib_libzstd_so_1";
const char* lib_libblkid_so_1 = "lib_libblkid_so_1";
const char* lib_libpam_so_0 = "lib_libpam_so_0";
const char* lib_libselinux_so_1 = "lib_libselinux_so_1";

void* dlopen(const char *path, int mode) {
	if (path == NULL) { return &main_program_handle; }
	if (strcmp( path, "libkmod.so.2" ) == 0) { dbg_print("(dlopen) found library libkmod.so.2 (handle=%p)\n", &lib_libkmod_so_2); return &lib_libkmod_so_2; }
	if (strcmp( path, "libmount.so.1" ) == 0) { dbg_print("(dlopen) found library libmount.so.1 (handle=%p)\n", &lib_libmount_so_1); return &lib_libmount_so_1; }
	if (strcmp( path, "libacl.so.1" ) == 0) { dbg_print("(dlopen) found library libacl.so.1 (handle=%p)\n", &lib_libacl_so_1); return &lib_libacl_so_1; }
	if (strcmp( path, "libcrypto.so.3" ) == 0) { dbg_print("(dlopen) found library libcrypto.so.3 (handle=%p)\n", &lib_libcrypto_so_3); return &lib_libcrypto_so_3; }
	if (strcmp( path, "libzstd.so.1" ) == 0) { dbg_print("(dlopen) found library libzstd.so.1 (handle=%p)\n", &lib_libzstd_so_1); return &lib_libzstd_so_1; }
	if (strcmp( path, "libblkid.so.1" ) == 0) { dbg_print("(dlopen) found library libblkid.so.1 (handle=%p)\n", &lib_libblkid_so_1); return &lib_libblkid_so_1; }
	if (strcmp( path, "libpam.so.0" ) == 0) { dbg_print("(dlopen) found library libpam.so.0 (handle=%p)\n", &lib_libpam_so_0); return &lib_libpam_so_0; }
	if (strcmp( path, "libselinux.so.1" ) == 0) { dbg_print("(dlopen) found library libselinux.so.1 (handle=%p)\n", &lib_libselinux_so_1); return &lib_libselinux_so_1; }
	fprintf(stderr, "(dlopen) WARNING: failed for path %s\n", path);	return stub_dlopen(path, mode);
}

